        one(4, 'At night, a central district may be several ______ warmer than the countryside.', 'degrees'),
        one(5, 'On a roof in summer, bees may have to look for ______ in swimming pools or leaking pipes.', 'water'),
        one(6, 'Many beekeeping courses are taught by experienced ______ rather than professionals.', 'volunteers'),
        one(7, 'Bees swarm when their colony becomes too ______.', 'crowded'),
        _q(8, 'true_false_notgiven', 'Pollution has been shown to make honey from city hives unsafe to eat.', ['FALSE'], TFNG),
        _q(9, 'true_false_notgiven', 'Swarming bees are usually aggressive towards passers-by.', ['FALSE'], TFNG),
        _q(10, 'true_false_notgiven', 'In one capital city, wild bees visited fewer flowers in streets with many hives.', ['TRUE'], TFNG),
