        _q(16, 'matching', 'an account of how keepers coped when medical help was far away', ['C'], sections),
        _q(17, 'matching', 'a reference to technology that stopped keepers having to climb the tower every few hours', ['E'], sections),
        _q(18, 'matching', 'a description of how former lighthouses are used today', ['G'], sections),
        one(19, 'Supplies reached the station by ______ when the sea allowed.', 'boat'),
        one(20, 'Children were taught by their parents and ______ were grown in small walled gardens.', 'vegetables'),
        one(21, 'At the most isolated stations, a sick keeper had no ______ within reach.', 'doctor'),
